    client = genai.Client(api_key=os.environ.get("GEMINI_API_KEY"), http_options=types.HttpOptions(base_url=os.environ.get("GOOGLE_GEMINI_BASE_URL")))

    response = client.models.generate_content_stream(
        model="{{cloudRun.model}}",
        contents=[
                {{#cloudRun.contents}}
                types.Content(
                    {{#role}}role="{{.}}",{{/role}}
                    parts=[
                        {{#parts}}
                        {{#text}}
                        types.Part.from_text(text="""{{.}}"""),
                        {{/text}}
                        {{#fileData.youtubeUrl}}
                        types.Part(
                            file_data=types.FileData(
                                file_uri="{{.}}",
                                mime_type="{{&fileData.mimeType}}",
                                {{#mediaResolution}}
                                media_resolution="{{mediaResolution.level}}",
                                {{/mediaResolution}}
                            ){{#fileData.videoMetadata}},{{/fileData.videoMetadata}}
                            {{#fileData.videoMetadata}}
                            video_metadata=types.VideoMetadata(
                                {{#fileData.videoMetadata.startOffset}}
                                start_offset="{{.}}s",
                                {{/fileData.videoMetadata.startOffset}}
                                {{#fileData.videoMetadata.endOffset}}
                                end_offset="{{.}}s",
                                {{/fileData.videoMetadata.endOffset}}
                                {{#fileData.videoMetadata.fps}}
                                fps={{&fileData.videoMetadata.fps}},
                                {{/fileData.videoMetadata.fps}}
                            ),
                            {{/fileData.videoMetadata}}
                        ),
                        {{/fileData.youtubeUrl}}
                        {{#inlineData}}
                        types.Part.from_bytes(
                            mime_type="{{&inlineData.mimeType}}",
                            data=base64.b64decode(
                                """{{&inlineData.data}}"""
                            ),
                            {{#videoMetadata}}
                            video_metadata=types.VideoMetadata(
                                {{#videoMetadata.startOffset}}
                                start_offset="{{.}}s",
                                {{/videoMetadata.startOffset}}
                                {{#videoMetadata.endOffset}}
                                end_offset="{{.}}s",
                                {{/videoMetadata.endOffset}}
                                {{#videoMetadata.fps}}
                                fps={{&videoMetadata.fps}},
                                {{/videoMetadata.fps}}
                            )
                            {{/videoMetadata}}
                            {{#mediaResolution}}
                            media_resolution="{{mediaResolution.level}}",
                            {{/mediaResolution}}
                        ),
                        {{/inlineData}}
                        {{#executableCode}}
                        types.Part.from_executable_code(
                            code="""{{code}}""",
                            language=types.Language.{{language}},
                        ),
                        {{/executableCode}}
                        {{#codeExecutionResult}}
                        types.Part.from_code_execution_result(
                            outcome=types.Outcome.{{&outcome}},
                            output="""{{output}}""",
                        ),
                        {{/codeExecutionResult}}
                        {{#functionCall}}
                        types.Part.from_function_call(
                            name="""{{name}}""",
                            args={{&parameters}},
                        ),
                        {{/functionCall}}
                        {{#functionResponse}}
                        types.Part.from_function_response(
                            name="""{{name}}""",
                            response={
                                "output": """{{response}}""",
                            },
                        ),
                        {{/functionResponse}}
                        {{/parts}}
                    ],
                ),
                {{/cloudRun.contents}}
        ]
    )
    for chunk in response:
        print(chunk.text, end="")


if __name__ == "__main__":
    generate()


