set -e -E

# To run this script, install jq for JSON processing

GEMINI_API_KEY="$GEMINI_API_KEY"
MODEL_ID="{{generateImages.model}}"

cat << EOF > request.json
{
    "instances": [
        {
            "prompt": "{{generateImages.prompt}}"
        }
    ],
    "parameters": {
        "sampleCount": {{generateImages.numberOfImages}},
        {{#generateImages.personGeneration}}
        "personGeneration": "{{generateImages.personGeneration}}",
        {{/generateImages.personGeneration}}
        {{#generateImages.aspectRatio}}
        "aspectRatio": "{{generateImages.aspectRatio}}",
        {{/generateImages.aspectRatio}}
        {{#generateImages.imageSize}}
        "imageSize": "{{.}}",
        {{/generateImages.imageSize}}
    }
}
EOF

# Store the full response from curl.
# Added -sS for silent operation (no progress meter) but to show errors if curl itself fails.
API_RESPONSE=$(curl \
    -X POST \
    -H "Content-Type: application/json" \
    -sS \
    "https://generativelanguage.googleapis.com/v1beta/${MODEL_ID}:predict?key=${GEMINI_API_KEY}" -d '@request.json'
)

# Check if the response contains any predictions
PREDICTION_COUNT=$(echo "$API_RESPONSE" | jq '.predictions | length')
if [[ "$PREDICTION_COUNT" == "null" || "$PREDICTION_COUNT" -eq 0 ]]; then
    echo "No images generated."
    exit 0
fi

{{#generateImages.numberOfImages}}
if [[ "$PREDICTION_COUNT" -ne {{generateImages.numberOfImages}} ]]; then
    echo "Number of images generated does not match the requested number."
fi
{{/generateImages.numberOfImages}}

# Initialize a counter for image filenames
image_count=0

# Define the image types array from the generated images.
IMAGE_TYPES=({{#generateImages.generatedImageTypes}}"{{.}}" {{/generateImages.generatedImageTypes}})

# Process each prediction:
# 1. Use jq to extract all 'bytesBase64Encoded' strings from the 'predictions' array.
#    The '.predictions[]?.bytesBase64Encoded' path gets each string.
#    The '[]' iterates over the array.
#    The '?' makes it safe if 'predictions' is null or an item lacks 'bytesBase64Encoded'.
# 2. Pipe each Base64 string to a while loop.
echo "$API_RESPONSE" | jq -r '.predictions[]?.bytesBase64Encoded' | while IFS= read -r b64_data; do
    # Increment image counter for unique filenames
    image_count=$((image_count + 1))
    idx=$((image_count - 1))

    # Check if b64_data is actually null (as a string from jq) or empty
    if [[ "$b64_data" = "null" ]] || [[ -z "$b64_data" ]]; then
        echo "Image $image_count was filtered."
        continue # Skip to the next iteration
    fi

    # Get the file extension for this image from the array, defaulting to jpeg.
    if [[ $idx -lt ${#IMAGE_TYPES[@]} ]]; then
        IMAGE_EXTENSION="${IMAGE_TYPES[$idx]}"
    else
        IMAGE_EXTENSION="jpeg"
    fi

    # Decode the Base64 string and save it to a uniquely named file
    echo "$b64_data" | base64 --decode > "image_${image_count}.${IMAGE_EXTENSION}"
    if [[ $? -eq 0 ]]; then
        echo "Saved image_${image_count}.${IMAGE_EXTENSION}"
    else
        # This error might occur if b64_data is invalid or disk is full, etc.
        echo "Error: Failed to decode or save image_${image_count}.${IMAGE_EXTENSION}."
    fi
done
