func writeWavFile(filename string, pcm []byte, channels, rate, sampleWidth int) {
  dataSize := len(pcm)
  byteRate := rate * channels * sampleWidth
  blockAlign := channels * sampleWidth
  header := make([]byte, 44)

  copy(header[0:4], "RIFF")
  binary.LittleEndian.PutUint32(header[4:8], uint32(36+dataSize))
  copy(header[8:12], "WAVE")
  copy(header[12:16], "fmt ")
  binary.LittleEndian.PutUint32(header[16:20], 16)
  binary.LittleEndian.PutUint16(header[20:22], 1)
  binary.LittleEndian.PutUint16(header[22:24], uint16(channels))
  binary.LittleEndian.PutUint32(header[24:28], uint32(rate))
  binary.LittleEndian.PutUint32(header[28:32], uint32(byteRate))
  binary.LittleEndian.PutUint16(header[32:34], uint16(blockAlign))
  binary.LittleEndian.PutUint16(header[34:36], uint16(sampleWidth*8))
  copy(header[36:40], "data")
  binary.LittleEndian.PutUint32(header[40:44], uint32(dataSize))

  out := append(header, pcm...)
  if err := os.WriteFile(filename, out, 0644); err != nil {
    log.Fatal(err)
  }
  fmt.Println("Audio saved to " + filename)
}

