def download_video(client, video_output, output_path):
    if not video_output:
        return

    data = getattr(video_output, 'data', None)
    if data:
        with open(output_path, "wb") as f:
            f.write(base64.b64decode(data))
        print(f"💾 Saved video to {output_path}")
        return
