function createWavFile(pcm: Uint8Array, channels = 1, rate = 24000, sampleWidth = 2): Uint8Array {
    const dataSize = pcm.length;
    const byteRate = rate * channels * sampleWidth;
    const blockAlign = channels * sampleWidth;
    const header = Buffer.alloc(44);

    header.write('RIFF', 0);
    header.writeUInt32LE(36 + dataSize, 4);
    header.write('WAVE', 8);
    header.write('fmt ', 12);
    header.writeUInt32LE(16, 16);
    header.writeUInt16LE(1, 20);
    header.writeUInt16LE(channels, 22);
    header.writeUInt32LE(rate, 24);
    header.writeUInt32LE(byteRate, 28);
    header.writeUInt16LE(blockAlign, 32);
    header.writeUInt16LE(sampleWidth * 8, 34);
    header.write('data', 36);
    header.writeUInt32LE(dataSize, 40);

    const result = new Uint8Array(header.length + pcm.length);
    result.set(new Uint8Array(header.buffer, header.byteOffset, header.byteLength), 0);
    result.set(pcm, header.length);
    return result;
}
